-- Management-only rollback. No browser wrapper or execution grant.
create function operations_private.hub_baseline_compensate_v1(p_source text,p_expected_head uuid,p_restore_version uuid,p_request_id uuid,p_operator text,p_reason text)
returns jsonb language plpgsql security invoker set search_path=pg_catalog set lock_timeout='5s' set statement_timeout='60s' as $$
declare head uuid; number integer; existing operations_private.hub_baseline_versions%rowtype; result_id uuid; changed integer;
begin
 if p_request_id is null or length(btrim(coalesce(p_operator,'')))=0 or length(btrim(coalesce(p_reason,'')))<10 then raise exception 'reviewed compensation identity/reason required';end if;
 perform pg_advisory_xact_lock(hashtextextended('hub-baseline-compensate:'||p_request_id,0));
 select * into existing from operations_private.hub_baseline_versions where request_id=p_request_id;
 if found then
  if existing.source is distinct from p_source or existing.event<>'restore' or existing.previous_version_id is distinct from p_expected_head or existing.created_by is distinct from (p_operator||' | restore='||p_restore_version||' | '||p_reason) then raise exception 'compensation request identity mismatch';end if;
  return jsonb_build_object('version_id',existing.id,'version',existing.version,'reused',true);
 end if;
 select h.current_version_id,v.version into head,number from operations_private.hub_baseline_heads h join operations_private.hub_baseline_versions v on v.id=h.current_version_id where h.source=p_source for update of h;
 if head is distinct from p_expected_head then raise exception 'compensation CAS conflict';end if;
 if p_restore_version is null or p_restore_version=head or not exists(
  with recursive ancestry as (select id,previous_version_id from operations_private.hub_baseline_versions where id=head and source=p_source union all select v.id,v.previous_version_id from operations_private.hub_baseline_versions v join ancestry a on a.previous_version_id=v.id where v.source=p_source) select 1 from ancestry where id=p_restore_version
 ) then raise exception 'restore version must be a previous version of this seller';end if;
 select count(*) into changed from (select * from operations_private.hub_baseline_rows where version_id=head) a full join (select * from operations_private.hub_baseline_rows where version_id=p_restore_version) b on a.product_code=b.product_code and a.option_code=b.option_code where a.facts is distinct from b.facts;
 insert into operations_private.hub_baseline_versions(source,version,previous_version_id,request_id,event,operation_count,confirmed_at,created_by) values(p_source,number+1,head,p_request_id,'restore',changed,clock_timestamp(),p_operator||' | restore='||p_restore_version||' | '||p_reason) returning id into result_id;
 insert into operations_private.hub_baseline_rows(version_id,product_code,option_code,facts,source_row_no,source_file_name) select result_id,product_code,option_code,facts,source_row_no,source_file_name from operations_private.hub_baseline_rows where version_id=p_restore_version;
 update operations_private.hub_baseline_heads set current_version_id=result_id where source=p_source and current_version_id=head;
 if not found then raise exception 'compensation CAS conflict';end if;
 return jsonb_build_object('version_id',result_id,'version',number+1,'restored_from',p_restore_version,'changed_rows',changed,'reused',false);
end $$;
revoke all on function operations_private.hub_baseline_compensate_v1(text,uuid,uuid,uuid,text,text) from public,anon,authenticated;
